"""Phase 4.1 host/terminal integration over real HTTP; no physical host or TV input."""
import json,unittest,urllib.request,urllib.error
from test_umbra_browser import UmbraBrowser
class CommandBridge(UmbraBrowser):
 def req(self,path,payload=None,headers=None):
  req=urllib.request.Request(self.url+path,json.dumps(payload).encode() if payload is not None else None,headers={'Content-Type':'application/json',**(headers or {})})
  try:
   with urllib.request.urlopen(req) as r:return r.status,json.load(r)
  except urllib.error.HTTPError as e:return e.code,json.load(e)
 def test_auto_local_bootstrap_and_single_server_authority_without_manual_key(self):
  p=self.page(pc=True);p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');self.assertTrue(p.evaluate('ICARUSHost.canWrite()'));c=self.browser.new_context();self.contexts.append(c);q=c.new_page();q.goto(self.url+'/icarus.html?icarus_soak=1');q.wait_for_function('!!window.__icarusSoak');self.assertFalse(q.evaluate('ICARUSHost.canWrite()'));before=q.evaluate('__icarusSoak.time()');q.evaluate('__icarusSoak.advance(5)');self.assertEqual(q.evaluate('__icarusSoak.time()'),before)
 def test_local_bootstrap_rejects_lan_host_header_and_remote_document_redirects(self):
  # A local peer with non-loopback Host is not the approved host launch URL.
  code,d=self.req('/api/icarus/bootstrap',headers={'Host':'192.168.1.123'});self.assertEqual(code,403)
  r=urllib.request.Request(self.url+'/icarus.html',headers={'Host':'192.168.1.123'})
  with urllib.request.urlopen(r) as response:self.assertIn('terminal=icarus',response.url);self.assertNotIn('world-schema.js',response.read().decode())
 def test_dispatch_ack_dedup_and_world_is_authoritative(self):
  p=self.page(pc=True);p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');auth={'Authorization':'Bearer test-client'}
  a=self.req('/api/icarus/dispatch',{'command':'nav:hold','requestId':'test-idempotent'},auth);b=self.req('/api/icarus/dispatch',{'command':'nav:hold','requestId':'test-idempotent'},auth);self.assertEqual(a[1]['queued'],b[1]['queued']);p.wait_for_function('__icarusSoak.snapshot().navigation.hold');p.wait_for_timeout(1800);self.assertEqual(self.m.BRIDGE_SERVICE.queue,[])
  code,_=self.req('/api/icarus/dispatch',{'command':'speed20','requestId':'creator-denied'},auth);self.assertEqual(code,403)
 def test_stale_remote_state_never_becomes_a_save_upload(self):
  self.assertEqual(self.req('/api/icarus/host/publish',{'telemetry':{'tick':99999}}, {'Authorization':'Bearer test-client'})[0],403)
  p=self.page(pc=True);p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');code,d=self.req('/api/icarus/live',headers={'Authorization':'Bearer test-client'});self.assertEqual(code,200);self.assertEqual(d['telemetry']['tick'],p.evaluate('__icarusSoak.time()'));self.assertEqual(d['state'],'SIMULATION PAUSED')
 def test_creator_shortcut_hides_controls_and_returns_to_bridge_after_reload(self):
  p=self.page(pc=True);self.assertFalse(p.locator('#pause').is_visible());self.assertEqual(p.locator('body').get_attribute('data-bridge-mode'),'bridge');p.keyboard.press('Control+Shift+F12');self.assertEqual(p.locator('body').get_attribute('data-bridge-mode'),'creator');self.assertTrue(p.locator('#pause').is_visible());p.reload();p.wait_for_function('!!window.__icarusSoak');self.assertEqual(p.locator('body').get_attribute('data-bridge-mode'),'bridge');self.assertTrue(p.evaluate('ICARUSHost.canWrite()'))
 def test_modular_workspace_resize_collapse_focus_presets_and_mobile_isolation(self):
  p=self.page(pc=True);p.locator('#workspace-lock').click();tile=p.locator('[data-widget-id=hologram]');width=tile.bounding_box()['width'];tile.locator('.workspace-width').select_option('3');self.assertLess(tile.bounding_box()['width'],width*.65);tile.locator('.workspace-height').fill('420');tile.locator('.workspace-height').dispatch_event('change');self.assertEqual(round(tile.bounding_box()['height']),420);tile.locator('.workspace-collapse').click();self.assertEqual(tile.get_attribute('data-collapsed'),'true');tile.locator('.workspace-collapse').click();tile.locator('.workspace-focus').click();self.assertIn('workspace-focused',tile.get_attribute('class'));p.keyboard.press('Escape');self.assertNotIn('workspace-focused',tile.get_attribute('class'));p.locator('#workspace-name').fill('Operations');p.locator('#workspace-save').click();before=p.evaluate("JSON.parse(localStorage.getItem('icarus-command-workspace-v1')).modes.desktop");p.set_viewport_size({'width':393,'height':851});p.wait_for_function("ICARUSWorkspace.mode==='mobile'");p.locator('[data-widget-id=hologram] .workspace-height').fill('240');p.locator('[data-widget-id=hologram] .workspace-height').dispatch_event('change');self.assertEqual(p.evaluate("JSON.parse(localStorage.getItem('icarus-command-workspace-v1')).modes.desktop"),before);p.set_viewport_size({'width':1280,'height':800});p.wait_for_function("ICARUSWorkspace.mode==='desktop'");self.assertEqual(p.locator('#workspace-preset').input_value(),'Operations');self.assertEqual(round(p.locator('[data-widget-id=hologram]').bounding_box()['height']),420)
 def test_hologram_wheel_does_not_trap_page_and_select_keeps_its_dom(self):
  p=self.page(pc=True);canvas=p.locator('#holo-canvas');box=canvas.bounding_box();p.mouse.move(box['x']+50,box['y']+50);p.mouse.wheel(0,500);p.wait_for_timeout(250);self.assertGreater(p.evaluate('scrollY'),0);p.keyboard.press('Control+Shift+F12');p.evaluate("ICARUSCommandUI.navigate('ship','overview')");p.locator('#cutawaymode').focus();p.evaluate("window.beforeSelect=document.querySelector('#cutawaymode')");p.evaluate('__icarusSoak.advance(1)');self.assertTrue(p.evaluate("beforeSelect===document.querySelector('#cutawaymode')&&document.activeElement===beforeSelect"))
 def test_live_phone_matches_host_and_recovers_without_creating_a_world(self):
  pc=self.page(pc=True);phone=self.page(width=393,height=851);self.tab(phone,'icarus');phone.wait_for_function("UmbraLive.state==='SIMULATION PAUSED'");self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertIsNone(phone.evaluate("localStorage.getItem('icarus-anthology-v14')"));pc.evaluate('__icarusSoak.advance(3)');tick=pc.evaluate('__icarusSoak.time()');phone.wait_for_function('(tick)=>UmbraLive.current.telemetry.tick===tick',arg=tick);phone.evaluate("Object.defineProperty(crypto,'randomUUID',{value:undefined,configurable:true})");phone.locator('[data-tablet-nav=hold]').click();pc.wait_for_function('__icarusSoak.snapshot().navigation.hold');before=pc.evaluate('__icarusSoak.snapshot()');phone.context.set_offline(True);phone.wait_for_function("UmbraLive.state==='RECONNECTING'",timeout=20000);self.assertIn('RECONNECTING',phone.locator('#icarusLink').inner_text());self.assertTrue(phone.locator('[data-tablet-nav=hold]').is_disabled());phone.context.set_offline(False);phone.wait_for_function("UmbraLive.state==='SIMULATION PAUSED'",timeout=30000);self.assertEqual(pc.evaluate('__icarusSoak.snapshot()'),before);self.assertEqual(phone.evaluate('UmbraLive.current.telemetry.tick'),before['tick']);self.assertLessEqual(phone.evaluate('document.documentElement.scrollWidth'),393)
 def test_camera_wall_profiles_keep_dom_and_source_labels(self):
  pc=self.page(pc=True);phone=self.page();self.tab(phone,'icarus');phone.wait_for_function("!!UmbraLive.current?.telemetry?.operations");profile=phone.locator('#umbra-operational-dashboard .op-person');profile.select_option('Frank Morrow');phone.evaluate("window.profileNode=document.querySelector('#umbra-operational-dashboard .op-person')");pc.evaluate('__icarusSoak.advance(1)');phone.wait_for_timeout(1600);self.assertTrue(phone.evaluate("profileNode===document.querySelector('#umbra-operational-dashboard .op-person')"));self.assertIn('No documented assessment',phone.locator('#umbra-operational-dashboard .op-profile').inner_text());tile=phone.locator('#umbra-operational-dashboard [data-camera=C05]');self.assertIn('LIVE STATE PROJECTION',tile.inner_text());tile.locator('.op-camera-focus').click();self.assertTrue(tile.evaluate("e=>e.classList.contains('op-camera-focused')"));phone.keyboard.press('Escape');self.assertFalse(tile.evaluate("e=>e.classList.contains('op-camera-focused')"))
 def test_workspace_pointer_move_resize_and_layout_never_change_the_world(self):
  p=self.page(pc=True);p.set_viewport_size({'width':1280,'height':1200});before=p.evaluate('__icarusSoak.snapshot()');p.locator('#workspace-lock').click();tile=p.locator('[data-widget-id=hologram]');tile.scroll_into_view_if_needed();a=tile.locator('.workspace-drag').bounding_box();b=p.locator('[data-widget-id=incidents]').bounding_box();p.mouse.move(a['x']+10,a['y']+10);p.mouse.down();p.mouse.move(b['x']+b['width']/2,b['y']+30,steps=6);p.mouse.up();self.assertEqual(p.evaluate("JSON.parse(localStorage.getItem('icarus-command-workspace-v1')).modes.desktop.presets.Custom.order[0]"),'incidents');handle=tile.locator('.workspace-resize');handle.scroll_into_view_if_needed();r=handle.bounding_box();height=tile.bounding_box()['height'];p.mouse.move(r['x']+5,r['y']+5);p.mouse.down();p.mouse.move(r['x']+60,r['y']+90,steps=6);p.mouse.up();self.assertGreater(tile.bounding_box()['height'],height);self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before)
 def test_creator_psychological_profile_retains_disclosure_and_scroll_on_live_refresh(self):
  p=self.page(pc=True);p.keyboard.press('Control+Shift+F12');p.evaluate("ICARUSCommandUI.navigate('personnel','social')");details=p.locator('#horrormonitor details');details.evaluate('e=>e.open=true');roster=p.locator('#horrormonitor .psych-roster');roster.evaluate('e=>e.scrollTop=80');before=roster.evaluate('e=>e.scrollTop');self.assertGreater(before,0);p.evaluate('__icarusSoak.advance(1)');self.assertTrue(p.locator('#horrormonitor details').evaluate('e=>e.open'));self.assertEqual(p.locator('#horrormonitor .psych-roster').evaluate('e=>e.scrollTop'),before);p.keyboard.press('Control+Shift+F12');self.assertEqual(p.locator('#horrormonitor').inner_text(),'')
 def test_unacknowledged_delivery_survives_reload_without_reexecuting_the_command(self):
  p=self.page(pc=True);p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');auth={'Authorization':'Bearer test-client'}
  def publish(route):
   if route.request.post_data_json.get('acks'):route.abort()
   else:route.continue_()
  p.route('**/api/icarus/host/publish',publish);code,d=self.req('/api/icarus/dispatch',{'command':'nav:hold','requestId':'reload-command'},auth);self.assertEqual(code,200);p.wait_for_function('__icarusSoak.snapshot().navigation.hold');p.evaluate('ICARUSDurable.flush()');count=p.evaluate('__icarusSoak.snapshot().chronicle.records.filter(r=>r.message.startsWith("SOL directive hold:")).length');self.assertEqual(count,1);self.assertEqual(len(self.m.BRIDGE_SERVICE.queue),1);p.unroute('**/api/icarus/host/publish',publish);p.reload();p.wait_for_function('!!window.__icarusSoak');p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');self.assertTrue(p.evaluate('ICARUSHost.canWrite()'));self.assertEqual(p.evaluate('__icarusSoak.snapshot().chronicle.records.filter(r=>r.message.startsWith("SOL directive hold:")).length'),count);self.assertEqual(self.m.BRIDGE_SERVICE.queue,[])
 def test_duplicate_tab_with_cloned_session_identity_is_still_a_spectator(self):
  p=self.page(pc=True)
  with p.expect_popup() as popup:p.evaluate("window.open('/icarus.html?icarus_soak=1','_blank')")
  q=popup.value;q.wait_for_function('!!window.__icarusSoak');self.assertEqual(p.evaluate('ICARUSHost.instance'),q.evaluate('ICARUSHost.instance'));self.assertTrue(p.evaluate('ICARUSHost.canWrite()'));self.assertFalse(q.evaluate('ICARUSHost.canWrite()'));self.assertFalse(q.evaluate('ICARUSDurable.canWrite()'))
 def test_bridge_observed_crew_follow_and_creator_route_recovery(self):
  p=self.page(pc=True);before=p.evaluate('__icarusSoak.snapshot()');self.assertNotIn('×',p.locator('#command-clock').inner_text());p.locator('[data-bridge-follow="Mara Chen"]').click();self.assertTrue(p.locator('#page-operations').is_visible());self.assertIn('B07 Security Control',p.locator('#camstatus').inner_text());self.assertIn('MARA CHEN',p.locator('#status').inner_text());self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);p.keyboard.press('Control+Shift+F12');p.evaluate("ICARUSCommandUI.navigate('settings','advanced')");p.keyboard.press('Control+Shift+F12');self.assertTrue(p.locator('#area-settings-general').is_visible());self.assertFalse(p.locator('#area-settings-advanced').is_visible())
